using Application.Common.Interfaces; using Application.Common.Interfaces.Time; using Application.Features.Premium.Freelancer.RankProtection.DTOs; using Domain.Entities; using MediatR; using Microsoft.EntityFrameworkCore;
namespace Application.Features.Premium.Freelancer.RankProtection.GetRankProtection;
public sealed class GetRankProtectionQueryHandler : IRequestHandler<GetRankProtectionQuery, RankProtectionDto?> { private readonly IApplicationDbContext _context; private readonly IDateTimeService _clock; public GetRankProtectionQueryHandler(IApplicationDbContext context, IDateTimeService clock){_context=context;_clock=clock;} public async Task<RankProtectionDto?> Handle(GetRankProtectionQuery q,CancellationToken ct){var now=_clock.UtcNow;var row=await _context.Set<FreelancerRankProtection>().AsNoTracking().Where(x=>x.FreelancerProfile.UserId==q.UserId&&x.IsVacationModeEnabled&&x.CancelledAt==null&&x.RankProtectionStartedAt<=now&&x.RankProtectionEndsAt>now).OrderByDescending(x=>x.RankProtectionStartedAt).FirstOrDefaultAsync(ct);return row is null?null:RankProtectionMapper.Map(row);}}
internal static class RankProtectionMapper { internal static RankProtectionDto Map(FreelancerRankProtection x)=>new(x.FreelancerRankProtectionsId,x.IsVacationModeEnabled,x.RankProtectionStartedAt,x.RankProtectionEndsAt,x.RankProtectionReason,x.CancelledAt); }
